steps.script:
$l=@(Get-Content 'C:\TTiTTulares\ttittulares-mobile-trigger.log' -Tail 300)
$o=@{state='unknown'}
foreach($k in @('RESTORED_DRAFT_TOO_LARGE','RESTORED_DRAFT_BACKUP_EXISTS','RESTORED_DRAFT_FOCUS_FAILED','RESTORED_DRAFT_CLEAR_UNVERIFIED','Fresh tab has draft or chat content','OTHER_CHAT_ACTIVITY','NO_PROBE','COMPOSER_NOT_READY','NEW_CHAT_CONTROL_UNAVAILABLE','CHAT MESSAGE TIMEOUT')){if(@($l|Where-Object{$_ -match [regex]::Escape($k)}).Count){$o.state=$k}}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
